questionvariables.text:
/*Defining question variables: 4 <= aa <= 10, max(2, aa-2) <= bb < aa*/
aa: 4+rand(7);
bb: max(2, aa-2) + rand(aa - max(2, aa-2));

r1:aa+2*sin(theta);
r2:bb-sin(theta);

/*Worked solution*/
expr:solve(r1=r2,theta)[1];
expr1:rhs(solve(r1=r2,sin(theta))[1]);
final_expr:expr3-expr4;
alpha:decimalplaces(rhs(expr),2);/*theta*/
beta:decimalplaces(%pi+(-1*alpha),2);
theta_limits:alpha<=theta and theta<=beta;
r_limits:r2<=r and r<=r1;
r_int:int(r,r);
r_int_limits:int(r,r,r2,r1);
theta_int:int(r_int_limits,theta);
theta_int_limits:int(r_int_limits,theta,alpha,beta);
expr3:subst(beta,theta,theta_int);
expr4:subst(alpha,theta,theta_int);

/*Model answers*/
ta1:expr1;
ta2:alpha;
ta3:beta;
ta4:decimalplaces(theta_int_limits,2);

